package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                     // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.Zero // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.Zero      // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.Zero // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0                         // PIC 9(3) len=3 = 0
var WsPriceEd string                          // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string                           // PIC ZZ,ZZ9.99 len=9
var WsNetEd string                            // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string                          // PIC ZZ,ZZZ,ZZ9.99 len=13

var CurDiscRec DiscRec
var discLines []string
var discIndex int

func pow10Int64(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func fitPic(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	modInt := pow10Int64(intDigits + int(scale))
	scaled := v.Abs().Shift(scale).Truncate(0).IntPart()
	m := scaled % modInt
	res := decimal.New(m, -scale)
	if v.Sign() < 0 {
		res = res.Neg()
	}
	return res
}

func formatPic9(v int64, digits int) string {
	mod := pow10Int64(digits)
	vm := v % mod
	if vm < 0 {
		vm += mod
	}
	return fmt.Sprintf("%0*d", digits, vm)
}

func formatEdited(v decimal.Decimal, intDigits int, intTemplate string, decDigits int) string {
	scale := int32(decDigits)
	vt := v.Truncate(scale)
	absScaled := vt.Abs().Shift(scale).Truncate(0).IntPart()
	powDec := pow10Int64(decDigits)
	powInt := pow10Int64(intDigits)
	var intPart, fracPart int64
	if powDec != 0 {
		intPart = (absScaled / powDec) % powInt
		fracPart = absScaled % powDec
	} else {
		intPart = absScaled % powInt
		fracPart = 0
	}
	if intPart < 0 {
		intPart = -intPart
	}
	if fracPart < 0 {
		fracPart = -fracPart
	}
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	var sb strings.Builder
	suppress := true
	di := 0
	for i := 0; i < len(intTemplate); i++ {
		ch := intTemplate[i]
		switch ch {
		case ',':
			if suppress {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		case 'Z':
			d := intStr[di]
			di++
			if suppress && d == '0' {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(d)
				suppress = false
			}
		case '9':
			d := intStr[di]
			di++
			sb.WriteByte(d)
			suppress = false
		default:
			sb.WriteByte(ch)
		}
	}
	sb.WriteByte('.')
	fracStr := fmt.Sprintf("%0*d", decDigits, fracPart)
	sb.WriteString(fracStr)
	return sb.String()
}

func parsePriceField(s string) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.Zero
	}
	t = strings.ReplaceAll(s, " ", "")
	t = strings.TrimSpace(t)
	if t == "" {
		return decimal.Zero
	}
	// allow optional sign
	neg := false
	if len(t) > 0 && (t[0] == '+' || t[0] == '-') {
		if t[0] == '-' {
			neg = true
		}
		t = t[1:]
		if t == "" {
			return decimal.Zero
		}
	}
	// t should be digits only
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		fmt.Fprintf(os.Stderr, "invalid numeric field %q\n", s)
		os.Exit(1)
	}
	if neg {
		n = -n
	}
	return decimal.New(n, -2)
}

func parseIntField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	// remove embedded spaces as zeros? treat by removing
	nospace := strings.ReplaceAll(s, " ", "")
	nospace = strings.TrimSpace(nospace)
	if nospace == "" {
		return 0
	}
	n, err := strconv.ParseInt(nospace, 10, 64)
	if err != nil {
		fmt.Fprintf(os.Stderr, "invalid numeric field %q\n", s)
		os.Exit(1)
	}
	return n
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// COBOL OPEN INPUT on missing file: treat as empty only if not exist?
		// To match exact behaviour, exit with error unless file simply empty.
		// If file does not exist, treat as empty file (no records) to allow summary?
		// Check: if not exist, consider empty.
		if os.IsNotExist(err) {
			discLines = nil
			discIndex = 0
			ReadPara()
			for !isInputDone() {
				ProcessPara()
			}
			SummaryPara()
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)
	discLines = nil
	for scanner.Scan() {
		discLines = append(discLines, scanner.Text())
	}
	if serr := scanner.Err(); serr != nil {
		fmt.Fprintln(os.Stderr, serr)
		f.Close()
		os.Exit(1)
	}
	f.Close()
	discIndex = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if discIndex >= len(discLines) {
		WsEofFlag = "Y"
		return
	}
	line := discLines[discIndex]
	discIndex++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	CurDiscRec.DrItem = line[0:6]
	priceStr := line[6:13]
	pctStr := line[13:15]
	CurDiscRec.DrPrice = parsePriceField(priceStr)
	CurDiscRec.DrPct = parseIntField(pctStr)
	// keep only low-order digits for input fields (in case of overflow, though inputs fit)
	// PCT is 9(2): mod 100
	CurDiscRec.DrPct = CurDiscRec.DrPct % 100
	if CurDiscRec.DrPct < 0 {
		CurDiscRec.DrPct += 100
	}
	// price fit to 9(5)V99 without rounding (input already at scale)
	CurDiscRec.DrPrice = fitPic(CurDiscRec.DrPrice.Truncate(2), 5, 2)
}

func ProcessPara() {
	tmp := CurDiscRec.DrPrice.Mul(decimal.NewFromInt(CurDiscRec.DrPct)).Shift(-2)
	rounded := tmp.Round(2)
	WsDiscount = fitPic(rounded, 5, 2)
	tmp2 := CurDiscRec.DrPrice.Sub(WsDiscount)
	trunc := tmp2.Truncate(2)
	WsNet = fitPic(trunc, 5, 2)
	tmp3 := WsTotalNet.Add(WsNet).Truncate(2)
	WsTotalNet = fitPic(tmp3, 8, 2)
	WsCount = (WsCount + 1) % 1000
	WsPriceEd = formatEdited(CurDiscRec.DrPrice, 5, "ZZ,ZZ9", 2)
	WsDiscEd = formatEdited(WsDiscount, 5, "ZZ,ZZ9", 2)
	WsNetEd = formatEdited(WsNet, 5, "ZZ,ZZ9", 2)
	pctStr := formatPic9(CurDiscRec.DrPct, 2)
	line := CurDiscRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprintln(os.Stdout, line)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, 8, "ZZ,ZZZ,ZZ9", 2)
	countStr := formatPic9(WsCount, 3)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprintln(os.Stdout, line)
}

func main() {
	MainPara()
}
